// ===== قوائم منسدلة متعددة الاختيار (مدمجة) =====
function msCss(){if(document.getElementById('ms-css'))return;document.head.insertAdjacentHTML('beforeend','<style id="ms-css">#v>.card:has(.msbar),#opt>.card:has(.msbar){grid-column:1/-1}.msbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-top:8px}.msbar>input{flex:1 1 200px;min-width:160px}.msbar .btn{margin:0}.ms{position:relative}.msb{border:1.5px solid #d4a63a;background:#fff;color:#0a1a44;border-radius:10px;padding:10px 14px;font:inherit;font-weight:700;cursor:pointer;white-space:nowrap}.msb.on{background:#0a1a44;color:#f2cf6b}.mp{position:absolute;top:calc(100% + 6px);right:0;width:250px;background:#fff;border:1.5px solid #d4a63a;border-radius:12px;box-shadow:0 12px 30px #0a1a4430;z-index:50;padding:10px}.mp[hidden]{display:none}.mp .mq{margin-bottom:8px;padding:8px 10px}.ml{max-height:220px;overflow:auto}.ml label{display:block;margin:0;padding:6px 4px;color:#0a1a44;font-size:.88rem;font-weight:600;cursor:pointer}.ma{display:flex;gap:8px;margin-top:8px}.ma button{flex:1;border:0;background:#f1f4ff;color:#12307a;border-radius:8px;padding:6px;font:inherit;font-weight:700;cursor:pointer}</style>')}
function multiSel(id,label,pairs){return`<div class="ms" id="${id}"><button type="button" class="msb">${esc(label)} <span class="mc"></span> ▾</button><div class="mp" hidden><input class="mq" placeholder="بحث..."><div class="ml">${pairs.map(([v,t])=>`<label><input type="checkbox" value="${esc(v)}"> ${esc(t)}</label>`).join('')||'<small>لا توجد قيم</small>'}</div><div class="ma"><button type="button" data-a="all">تحديد الكل</button><button type="button" data-a="none">مسح</button></div></div></div>`}
function initMs(root){msCss();if(!window.__msc){window.__msc=1;document.addEventListener('click',e=>{if(!e.target.closest('.ms'))document.querySelectorAll('.mp').forEach(p=>p.hidden=true)})}
 root.querySelectorAll('.ms').forEach(m=>{const btn=m.querySelector('.msb'),pop=m.querySelector('.mp'),upd=()=>{const n=m.querySelectorAll('.ml input:checked').length;m.querySelector('.mc').textContent=n?'('+n+')':'';btn.classList.toggle('on',n>0)};
  btn.onclick=e=>{e.stopPropagation();document.querySelectorAll('.mp').forEach(p=>{if(p!==pop)p.hidden=true});pop.hidden=!pop.hidden};
  m.querySelector('.mq').oninput=e=>{const t=e.target.value.toLowerCase();m.querySelectorAll('.ml label').forEach(l=>l.style.display=l.textContent.toLowerCase().includes(t)?'':'none')};
  m.querySelector('.ml').onchange=upd;m.querySelectorAll('[data-a]').forEach(a=>a.onclick=()=>{m.querySelectorAll('.ml label').forEach(l=>{if(l.style.display!='none')l.querySelector('input').checked=a.dataset.a=='all'});upd()})})}
const msVals=id=>[...document.querySelectorAll('#'+id+' .ml input:checked')].map(i=>i.value);

